 override fun onDraw(c:Canvas){ super.onDraw(c); c.drawColor(Color.rgb(22,34,43)); val s=min(width/390f,height/780f); c.save(); c.scale(s,s); when(screen){"map"->drawMap(c);"location"->drawLocation(c);"prep"->drawPrep(c);"characters"->drawCharacters(c);"inventory"->drawInventory(c);"formation"->drawFormation(c);"battle"->drawBattle(c);"result"->drawResult(c)}; c.restore() }
