  box(c,18f,438f,372f,570f,Color.rgb(38,52,53)); text(c,"Nhân vật: "+names[selectedCharacter],195f,465f,16f,gold,true); text(c,if(selectedCharacter==0)"Trang phục: "+outfit else "Trang phục riêng của nhân vật",195f,492f,12f); button(c,"Mặc định",24f,510f,135f,548f); button(c,"Bạch Vân",145f,510f,255f,548f); button(c,"← Về chuẩn bị",80f,600f,310f,650f)
