 private fun drawBattle(c:Canvas){text(c,"CHIẾN ĐẤU THỬ • Trận $battleNo",195f,36f,19f,gold,true);text(c,"Theo lượt • hiệu ứng kiếm dùng chung",195f,59f,11f);box(c,12f,78f,378f,390f,Color.rgb(50,74,64),18f);paint(Color.rgb(85,118,86));c.drawRect(20f,270f,370f,380f,p);drawHero(c,70f,235f,outfit,System.currentTimeMillis()<slashUntil);for(i in 0..2){if(i+1<party.size)drawMiniHero(c,145f+i*38f,225f,i+1==activeMember)};drawMonster(c,320f,235f);text(c,"Đội hình ${party.size}/4",195f,305f,12f);text(c,"Yêu thú",320f,305f,12f);val hpLabels=listOf("Nguyệt Ly","Lâm Thanh","Mặc Vân","Hạ Linh","Nhân vật 5","Nhân vật 6");for((slot,id) in party.sorted().withIndex()){bar(c,18f,322f+slot*14f,145f,characterHp[id],100,"${hpLabels[id]}${if(id==activeMember) " *" else ""}",green)};text(c,"MP $mp/50",292f,365f,10f);bar(c,220f,324f,365f,enemyHp,85,"Quái",red);text(c,message,195f,416f,12f);box(c,15f,438f,375f,595f,Color.rgb(38,52,53));text(c,"Kỹ năng",195f,461f,16f,gold,true);button(c,"Kiếm Khí",25f,474f,185f,516f);button(c,"Phi Kiếm (-10 MP)",200f,474f,365f,516f);button(c,"Linh Kiếm Trận (-20 MP)",25f,525f,215f,567f);button(c,"Hồi Nguyên (-15 MP)",225f,525f,365f,567f,green);button(c,"Dùng đan ($pills)",25f,573f,185f,612f,green);button(c,if(auto)"TẮT TỰ ĐỘNG" else "BẬT TỰ ĐỘNG",200f,573f,365f,612f,if(auto)red else gold);button(c,"BỎ TRẬN / VỀ CHUẨN BỊ",35f,635f,355f,681f,Color.rgb(190,156,94));text(c,"Linh thạch: $stones   EXP: $exp",195f,716f,13f);text(c,"Ảnh 2D chỉ hiện khi nữ chính ra chiêu.",195f,744f,11f)}
 private fun drawMiniHero(c:Canvas,x:Float,y:Float,active:Boolean){paint(if(active)gold else Color.rgb(75,112,143));c.drawOval(RectF(x-12f,y-27f,x+12f,y+20f),p);paint(Color.rgb(231,194,172));c.drawCircle(x,y-30f,9f,p);if(active){paint(Color.WHITE,Paint.Style.STROKE,2f);c.drawCircle(x,y-8f,19f,p)}}
 private fun drawMonster(c:Canvas,x:Float,y:Float){paint(Color.rgb(75,93,67));c.drawOval(RectF(x-34,y-38,x+34,y+34),p);paint(Color.rgb(175,66,56));c.drawCircle(x-12,y-9,5f,p);c.drawCircle(x+12,y-9,5f,p);paint(Color.rgb(40,48,38));c.drawPath(Path().apply{moveTo(x-17,y+12);lineTo(x,y+22);lineTo(x+17,y+12)},p);paint(Color.rgb(65,76,59));c.drawPath(Path().apply{moveTo(x-25,y-23);lineTo(x-42,y-46);lineTo(x-7,y-31);close()},p);c.drawPath(Path().apply{moveTo(x+25,y-23);lineTo(x+42,y-46);lineTo(x+7,y-31);close()},p)}
 private fun bar(c:Canvas,l:Float,y:Float,r:Float,value:Int,max:Int,label:String,color:Int){text(c,"$label $value/$max",(l+r)/2,y-4,10f);box(c,l,y,r,y+9,Color.DKGRAY,4f);if(value>0)box(c,l,y,l+(r-l)*value/max,y+9,color,4f)}
 private fun drawResult(c:Canvas){text(c,"KẾT QUẢ TRẬN ĐẤU",195f,80f,23f,gold,true);drawHero(c,195f,240f,outfit,false);text(c,message,195f,330f,16f);text(c,"EXP: $exp    Linh thạch: $stones",195f,370f,15f);button(c,"ĐÁNH TRẬN TIẾP",35f,430f,355f,485f);button(c,"ĐỔI TRANG PHỤC",35f,505f,355f,560f);button(c,"VỀ BẢN ĐỒ",35f,580f,355f,635f)}
 private fun startBattle(){if(party.isEmpty()){message="Hãy chọn ít nhất một nhân vật xuất chiến.";screen="formation";return};for(i in characterHp.indices)characterHp[i]=100;mp=50;enemyHp=85;playerTurn=true;activeMember=party.sorted().first();auto=false;screen="battle";message="Mỗi nhân vật có HP riêng. Đến lượt nhân vật ${activeMember+1}."}
 private fun doTurn(skill:Int=0){if(screen!="battle"||enemyHp<=0||party.none{characterHp[it]>0})return;if(!playerTurn&&skill!=-1){message="Đang đến lượt quái vật.";return}
 if(playerTurn){when(skill){4->{if(pills<=0){message="Bạn đã hết đan hồi phục.";return};pills--;characterHp[activeMember]=(characterHp[activeMember]+35).coerceAtMost(100);message="Dùng đan, nhân vật ${activeMember+1} hồi 35 HP."};3->{if(mp<15){message="Không đủ MP.";return};mp-=15;characterHp[activeMember]=(characterHp[activeMember]+30).coerceAtMost(100);message="Hồi Nguyên Quyết: nhân vật ${activeMember+1} hồi 30 HP."};else->{val cost=if(skill==1)10 else if(skill==2)20 else 0;if(mp<cost){message="Không đủ MP!";return};mp-=cost;val damage=when(skill){1->38;2->52;else->25};enemyHp=(enemyHp-damage).coerceAtLeast(0);slashUntil=System.currentTimeMillis()+550;message="Nhân vật ${activeMember+1} dùng ${if(skill==0) "Kiếm Khí" else if(skill==1) "Phi Kiếm Quyết" else "Linh Kiếm Trận"}, gây $damage sát thương!";activeMember=party.sorted().firstOrNull{it>activeMember&&characterHp[it]>0}?:party.sorted().firstOrNull{characterHp[it]>0}?:activeMember;postInvalidateDelayed(570)}}
 if(enemyHp<=0){stones+=15;exp+=20;wins++;message="Chiến thắng! +15 linh thạch, +20 EXP.";auto=false;screen="result";return};playerTurn=false
 }else{val alive=party.sorted().filter{characterHp[it]>0};if(alive.isEmpty()){auto=false;screen="result";message="Toàn đội đã kiệt sức. Hãy thử lại!";return};if(activeMember !in alive)activeMember=alive.first();val damage=(12-(if(outfit=="Bạch Vân")2 else 0)).coerceAtLeast(5);characterHp[activeMember]=(characterHp[activeMember]-damage).coerceAtLeast(0);message="Yêu thú phản công, nhân vật ${activeMember+1} mất $damage HP.";val nextAlive=party.sorted().filter{characterHp[it]>0};if(nextAlive.isEmpty()){auto=false;screen="result";message="Toàn đội đã bại trận. Hãy thử lại!";return};activeMember=nextAlive.firstOrNull{it>activeMember}?:nextAlive.first();playerTurn=true}}}
 override fun onTouchEvent(e:MotionEvent):Boolean{if(e.action!=MotionEvent.ACTION_UP)return true;val s=min(width/390f,height/780f);val x=e.x/s;val y=e.y/s
 when(screen){
 "map"->if(y>695f)screen="prep" else if(y in 250f..370f&&x in 130f..255f){screen="location";message="Bạn đã đến Thanh Vân Tông."}else{message="Chạm ĐẤU THỬ để kiểm tra chiến đấu và trang phục.";invalidate()}
 "location"->if(y>610f&&x<190f)screen="map" else if(y>610f)screen="prep" else{message="NPC thử nghiệm. Có thể vào ĐẤU THỬ.";invalidate()}
 "prep"->when{y in 80f..120f->{when{x<136f->screen="characters";x<254f->screen="inventory";else->screen="formation"}};y in 385f..440f->{val choice=when{x<136f->"Mặc định";x<254f->"Bạch Vân";else->"Xích Hà"};if(choice in owned){outfit=choice;message="Đã chọn trang phục $outfit."}else message="Chưa sở hữu. Hãy nhận thưởng thử nghiệm."};y in 525f..568f&&x<195f->if("Bạch Vân" in owned)message="Bạn đã sở hữu Bạch Vân." else if(stones>=30){stones-=30;owned.add("Bạch Vân");outfit="Bạch Vân";message="Đã mua và trang bị Bạch Vân."}else message="Không đủ linh thạch.";y in 525f..568f&&x>=195f->{owned.add("Xích Hà");outfit="Xích Hà";message="Đã nhận Xích Hà từ nhiệm vụ thử nghiệm."};y in 635f..700f->startBattle();y>705f->{screen="map";message="Chạm ĐẤU THỬ để bắt đầu"}}
 "characters"->{when{y in 90f..420f->{val col=if(x<195f)0 else 1;val row=((y-92f)/112f).toInt().coerceIn(0,2);selectedCharacter=(row*2+col).coerceIn(0,5);message="Đã chọn xem nhân vật."};y in 505f..552f&&selectedCharacter==0->{if(x<140f){outfit="Mặc định";message="Đã chọn Mặc định."}else if("Bạch Vân" in owned){outfit="Bạch Vân";message="Đã chọn Bạch Vân."}else message="Chưa sở hữu Bạch Vân."};y>590f->{screen="prep"}}};"inventory"->{if(y>610f)screen="prep"};"formation"->{when{y in 110f..430f->{val col=if(x<195f)0 else 1;val row=((y-112f)/105f).toInt().coerceIn(0,2);val idx=(row*2+col).coerceIn(0,5);if(idx in party)party.remove(idx)else if(party.size<4)party.add(idx)else message="Đội hình đã đủ 4 nhân vật.";};y in 470f..525f->{message="Đội hình đã lưu: ${party.size}/4."};y>540f->screen="prep"}};"battle"->{if(y in 470f..520f&&playerTurn){if(x<195f)doTurn(0)else doTurn(1)}else if(y in 522f..570f&&playerTurn){if(x<220f)doTurn(2)else doTurn(3)}else if(y in 572f..615f){if(x<195f&&playerTurn)doTurn(4)else if(x>=195f){auto=!auto;if(auto)postDelayed(autoAction,300)}}else if(y in 630f..690f){auto=false;screen="prep";message="Đã rời trận. Đổi trang phục trước trận tiếp theo."};if(screen=="battle"&&!playerTurn&&!auto)postDelayed({if(screen=="battle"&&!playerTurn){doTurn(-1);invalidate()}},450)}
 "result"->when{y in 425f..490f->{battleNo++;startBattle()};y in 500f..565f->{screen="prep";message="Chọn trang phục trước khi vào trận."};y in 575f..645f->{screen="map";message="Số trận thắng: $wins"}}
 };invalidate();return true}
}
